Translate("ptBR", "western-plaguelands", {
	title = "Terras Pestilentas Ocidentais",
	aliases = { "as Terras Pestilentas Ocidentais" },
	sections = {
		{
			title = "Resumo",
			text = [=[As Terras Pestilentas Ocidentais foram um dia o coração setentrional de {link:lordaeron}Lordaeron{/link}: uma terra de fazendas onduladas, pomares, celeiros e cidades prósperas entre as clareiras de {link:tirisfal-glades}Tirisfal{/link} e o rio que corre para o leste. Hoje são uma terra cinzenta e envenenada. O capim secou, as árvores estão nuas, e os campos que alimentavam um reino agora alimentam apenas o {link:scourge}Flagelo{/link}. Grandes caldeirões exalam a praga no ar sobre as velhas fazendas. Os mortos andam pelas estradas. Ainda assim, a terra não está de todo perdida. Três poderes vieram disputá-la com os mortos: a {link:alliance}Aliança{/link} pelo sul, os {link:forsaken}Renegados{/link} pelo oeste e a {link:scarlet-crusade}Cruzada Escarlate{/link} a partir de sua fortaleza no norte. Nenhum deles confia nos outros.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra o ano em que estas terras foram povoadas pela primeira vez. Pertenceram ao reino de {link:lordaeron}Lordaeron{/link} enquanto esse reino existiu, e estavam entre as mais ricas dele. A cidade de {link:ruins-of-andorhal}Andorhal{/link} reunia em seus celeiros as colheitas do norte. A cidade de {link:hearthglen}Amparo{/link} e a Bastilha Mardenforte guardavam as colinas do norte, e nos anos após a {link:second-war}Segunda Guerra{/link} foram governadas por {link:tirion-fordring}Tirion Fordring{/link}, um lorde e paladino do Punho de Prata. No sul, a família Barov possuía o castelo insular de {link:caer-darrow}Castro das Flechas{/link} em seu lago tranquilo, e a nobreza do reino ia até lá para descansar e ter seus retratos pintados à beira d'água.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[O {link:scourge}Flagelo{/link} ainda governa as Terras Pestilentas Ocidentais. Um lich chamado {link:araj-the-summoner}Araj, o Invocador{/link}, domina as ruínas de {link:ruins-of-andorhal}Andorhal{/link}. Quatro caldeirões da praga, cuidados por senhores do caldeirão, envenenam as terras de cultivo. No sul, sob {link:caer-darrow}Castro das Flechas{/link}, o culto treina seus necromantes na Scolomântia.

Contra eles erguem-se pequenas forças nas bordas da terra. No {link:chillwind-camp}Acampamento Ventogelante{/link}, ao sul, o {link:commander-ashlam-valorfist}Comandante Ashlam Valorfist{/link} reúne os soldados e campeões da {link:alliance}Aliança{/link} sob o estandarte do {link:kingdom-of-stormwind}Reino de Ventobravo{/link}. No {link:the-bulwark}Baluarte{/link}, a oeste, o {link:high-executor-derrington}Alto Executor Derrington{/link} defende o portão leste de {link:tirisfal-glades}Tirisfal{/link} para os {link:forsaken}Renegados{/link} e a {link:horde}Horda{/link}. No norte, a {link:scarlet-crusade}Cruzada Escarlate{/link} domina {link:hearthglen}Amparo{/link} sob o {link:taelan-fordring}Grão-senhor Taelan Fordring{/link}. Ela combate o Flagelo, e combate todos os demais também. Agentes da {link:argent-dawn}Aurora Argêntea{/link} servem nos acampamentos da Aliança e da Horda, e não pedem nada a nenhum dos dois além da guerra contra os mortos.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}O {link:scourge}Flagelo{/link}.{/b} Esqueletos, carniçais, abominações, espectros e os espíritos inquietos dos afogados e dos mortos em batalha. Dominam {link:ruins-of-andorhal}Andorhal{/link}, a {link:sorrow-hill}Colina do Pesar{/link} e as velhas fazendas.
• {b}O {link:cult-of-the-damned}Culto dos Malditos{/link}.{/b} Servos vivos do Lich Rei que trabalham entre os mortos, em Andorhal e na Scolomântia.
• {b}A {link:alliance}Aliança{/link}.{/b} Soldados de {link:stormwind-city}Ventobravo{/link}, sacerdotes, alquimistas e agentes da {link:si-7}SI:7{/link} no {link:chillwind-camp}Acampamento Ventogelante{/link}.
• {b}Os {link:forsaken}Renegados{/link}.{/b} A guarnição do {link:the-bulwark}Baluarte{/link}, que defende a fronteira para {link:sylvanas-windrunner}a Dama Sombria{/link}.
• {b}A {link:scarlet-crusade}Cruzada Escarlate{/link}.{/b} Cavaleiros, sacerdotes e inquisidores de {link:hearthglen}Amparo{/link}, e os trabalhadores da serraria que tomaram em Beiranorte.
• {b}A {link:argent-dawn}Aurora Argêntea{/link}.{/b} Oficiais e defensores postados nos dois acampamentos.
• {b}Os mortos inquietos do velho reino.{/b} Fantasmas que nunca fizeram parte do Flagelo: os espíritos de {link:caer-darrow}Castro das Flechas{/link}, a mulher do {link:felstone-field}Campo Pedravil{/link}, os enlutados da Colina do Pesar.
• {b}Feras pestilentas.{/b} Lobos, ursos, morcegos e abutres, doentes da mesma praga que a terra.]=],
		},
		{
			title = "História",
			text = [=[• {b}O Reino.{/b} Por gerações, estas foram as terras de cultivo e as cidades ribeirinhas de {link:lordaeron}Lordaeron{/link}, ricas e pacíficas sob a força do reino.
• {b}A {link:second-war}Segunda Guerra{/link}.{/b} Quando a {link:horde}Horda{/link} órquica invadiu o norte, os cavaleiros do Punho de Prata cavalgaram contra ela. {link:tirion-fordring}Tirion Fordring{/link} estava entre eles. Depois da guerra, governou as terras em torno de {link:hearthglen}Amparo{/link}, até ser destituído delas por poupar a vida de um {link:orcs}orc{/link}.
• {b}A Praga.{/b} Antes da {link:third-war}Terceira Guerra{/link}, agentes do {link:cult-of-the-damned}Culto dos Malditos{/link} contaminaram os grãos nos celeiros de {link:ruins-of-andorhal}Andorhal{/link}, e os grãos foram levados às aldeias do norte. Os que os comeram adoeceram, morreram e se ergueram de novo como servos do Lich Rei. O Príncipe {link:arthas-menethil}Arthas Menethil{/link} veio a Andorhal e matou o mestre do culto, {link:kel-thuzad}Kel'Thuzad{/link}, mas a praga já tinha se espalhado além de qualquer cura, e o norte caiu uma cidade de cada vez.
• {b}A {link:fall-of-lordaeron}Queda de Lordaeron{/link}.{/b} Depois que Arthas assassinou o pai, o Punho de Prata foi desfeito. {link:uther-the-lightbringer}Uther, o Portador da Luz{/link}, morreu pela mão de seu aluno, e uma tumba foi erguida em sua memória nestas terras. Os Barov de {link:caer-darrow}Castro das Flechas{/link} entregaram seu castelo ao culto, e a Scolomântia foi fundada em suas criptas.
• {b}Os Dias de Hoje.{/b} O {link:scourge}Flagelo{/link} domina o coração da terra. Os vivos se agarram às suas bordas, e a Cruzada domina o norte.]=],
		},
		{
			title = "Saber das Terras Pestilentas",
			text = [=[• Os relógios de {link:ruins-of-andorhal}Andorhal{/link}, e o grande relógio na ruína de sua prefeitura, pararam todos na mesma hora. Foi a hora em que a praga tomou a cidade pela primeira vez.
• Na ilha de {link:caer-darrow}Castro das Flechas{/link}, dizem que os fantasmas dos moradores revivem sem parar seu último dia feliz, como se nada lhes tivesse acontecido.
• Os {link:forsaken}Renegados{/link} e a {link:alliance}Aliança{/link} dizem, ambos, que tomarão Andorhal. Nenhum diz o que fará com a cidade depois de tomá-la.
• Entre os mortos da {link:sorrow-hill}Colina do Pesar{/link} jazem muitos que caíram defendendo a {link:darrowshire}Vila das Flechas{/link}, a leste.]=],
		},
	},
})

Translate("ptBR", "chillwind-camp", {
	title = "Acampamento Ventogelante",
	sections = {
		{
			title = "Resumo",
			text = [=[O Acampamento Ventogelante é o ponto de apoio da {link:alliance}Aliança{/link} nas {link:western-plaguelands}Terras Pestilentas Ocidentais{/link}. Fica na borda sul da terra, acima das alturas de {link:alterac-mountains}Alterac{/link}, onde algumas tendas, uma forja e um poleiro de grifos se agarram à encosta. Daqui o {link:commander-ashlam-valorfist}Comandante Ashlam Valorfist{/link} planeja a guerra contra {link:ruins-of-andorhal}Andorhal{/link} em nome de {link:kingdom-of-stormwind}Ventobravo{/link}. Seus sacerdotes estudam a praga, seu alquimista estuda a Scolomântia, e um agente da {link:si-7}SI:7{/link} espera notícias do leste. Oficiais da {link:argent-dawn}Aurora Argêntea{/link} mantêm um posto entre eles. {link:weldon-barov}Weldon Barov{/link}, o último senhor vivo de sua casa, também vive aqui sob a proteção do acampamento.]=],
		},
	},
})

Translate("ptBR", "the-bulwark", {
	title = "O Baluarte",
	aliases = { "Baluarte" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Baluarte é o portão fortificado entre {link:tirisfal-glades}Tirisfal{/link} e as Terras Pestilentas. Sua muralha e suas torres foram erguidas para conter o {link:scourge}Flagelo{/link} longe das terras dos {link:forsaken}Renegados{/link}, e são os Renegados que as guarnecem agora. O {link:high-executor-derrington}Alto Executor Derrington{/link} comanda aqui. Do Baluarte, envia seus soldados a leste contra {link:ruins-of-andorhal}Andorhal{/link} e os caldeirões da praga, e ao norte contra a {link:scarlet-crusade}Cruzada Escarlate{/link}. Boticários e sacerdotes das sombras trabalham ao lado de seus soldados. A {link:argent-dawn}Aurora Argêntea{/link} também mantém oficiais no portão. Assim como {link:alexi-barov}Alexi Barov{/link}, um lorde renegado de uma casa caída, que espera aqui notícias da fortuna de sua família.]=],
		},
	},
})

Translate("ptBR", "ruins-of-andorhal", {
	title = "Ruínas de Andorhal",
	aliases = { "Andorhal" },
	sections = {
		{
			title = "Resumo",
			text = [=[Andorhal era a grande cidade-celeiro do norte de {link:lordaeron}Lordaeron{/link}. As colheitas do reino eram guardadas em seus silos, e deles o {link:cult-of-the-damned}Culto dos Malditos{/link} despachou os grãos contaminados que deram início à praga. Aqui o Príncipe {link:arthas-menethil}Arthas Menethil{/link} encurralou {link:kel-thuzad}Kel'Thuzad{/link} e o matou. Agora a cidade é uma ruína dominada pelo {link:scourge}Flagelo{/link}. Quatro torres de vigia guardam seus acessos, e no coração da cidade o lich {link:araj-the-summoner}Araj, o Invocador{/link}, mantém sua corte. Todos os relógios de Andorhal pararam na hora em que a praga a tomou. Na estalagem em ruínas no canto noroeste da cidade, uma estranha gnoma chamada {link:chromie}Chromie{/link} fez seu lar.]=],
		},
	},
})

Translate("ptBR", "hearthglen", {
	title = "Amparo",
	sections = {
		{
			title = "Resumo",
			text = [=[Amparo ergue-se nas colinas do extremo norte, olhando do alto para as Terras Pestilentas. Era a cidade de {link:tirion-fordring}Tirion Fordring{/link}, que governava estas terras a partir da Bastilha Mardenforte até ser banido. Na guerra contra o {link:scourge}Flagelo{/link}, o Príncipe {link:arthas-menethil}Arthas Menethil{/link} defendeu Amparo contra os mortos até que {link:uther-the-lightbringer}Uther{/link} viesse socorrê-lo. Hoje a cidade pertence à {link:scarlet-crusade}Cruzada Escarlate{/link}. Suas muralhas são patrulhadas por cruzados, seu castelo é a sede do {link:taelan-fordring}Grão-senhor Taelan Fordring{/link}, e sua estrada é vigiada de postos avançados ao longo do Desfiladeiro de Amparo. A Cruzada guarda a cidade com zelo. Alguns em {link:stormwind-city}Ventobravo{/link} acreditam que ela tem mais do que importância histórica.]=],
		},
	},
})

Translate("ptBR", "northridge-lumber-camp", {
	title = "Madeireira Beiranorte",
	aliases = { "Serraria Beiranorte" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Madeireira Beiranorte fica ao sul de {link:hearthglen}Amparo{/link}, a oeste da estrada que sobe até a cidade. Antes da praga era uma serraria onde as famílias do norte ganhavam o pão, cortando e serrando a madeira das colinas. A {link:scarlet-crusade}Cruzada Escarlate{/link} a tomou. Trabalhadores e lenhadores cruzados agora cortam madeira para as muralhas de Amparo, sob os olhos de seus capatazes. Os filhos das famílias que um dia trabalharam aqui não esqueceram. Um serve à {link:alliance}Aliança{/link} no {link:chillwind-camp}Acampamento Ventogelante{/link}, outro aos {link:forsaken}Renegados{/link} no {link:the-bulwark}Baluarte{/link}, e ambos querem a serraria arruinada em vez de deixada nas mãos da Cruzada.]=],
		},
	},
})

Translate("ptBR", "felstone-field", {
	title = "Campo Pedravil",
	sections = {
		{
			title = "Resumo",
			text = [=[O Campo Pedravil era a fazenda da família Felstone, a noroeste de {link:ruins-of-andorhal}Andorhal{/link}. A casa continua de pé, assim como o celeiro, mas seus campos agora servem ao {link:scourge}Flagelo{/link}. Um caldeirão da praga ergue-se entre eles, cuidado pelo senhor do caldeirão Bilemaw e pelos mais inexperientes dos mortos. No quarto de cima da casa da fazenda permanece o fantasma de {link:janice-felstone}Janice Felstone{/link}. Ela não sabe há quanto tempo espera ali. Fala de um pacote que pretendia enviar, e de seu marido John, como se a praga tivesse chegado ontem.]=],
		},
	},
})

Translate("ptBR", "dalson-s-tears", {
	title = "Lágrimas de Dalson",
	sections = {
		{
			title = "Resumo",
			text = [=[As Lágrimas de Dalson ficam quase exatamente ao norte de {link:ruins-of-andorhal}Andorhal{/link}. Era a fazenda da família Dalson, e o nome que carrega agora lhe foi dado depois da praga. Um caldeirão do {link:scourge}Flagelo{/link} ergue-se em seu campo. A casa da fazenda guarda um diário aberto em sua última página, um armário arranhado por mãos desesperadas e uma casinha cuja porta foi golpeada por dentro. Um esqueleto vagueia pelo quintal. A história que essas coisas contam é uma das mais tristes das Terras Pestilentas.]=],
		},
	},
})

Translate("ptBR", "the-writhing-haunt", {
	title = "O Antro Repelente",
	aliases = { "Antro Repelente" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Antro Repelente é uma fazenda em ruínas a leste de {link:ruins-of-andorhal}Andorhal{/link}, perto das muralhas partidas da cidade. O {link:scourge}Flagelo{/link} ergueu aqui um de seus caldeirões da praga, e o chão em volta fervilha de mortos. Numa cabana da fazenda jaz um druida {link:tauren}tauren{/link} que veio de longe para curar as feras desta terra. Não encontrou cura, e ele próprio contraiu a praga.]=],
		},
	},
})

Translate("ptBR", "gahrron-s-withering", {
	title = "Aridez de Garrão",
	sections = {
		{
			title = "Resumo",
			text = [=[A Aridez de Garrão é uma fazenda morta no nordeste das {link:western-plaguelands}Terras Pestilentas Ocidentais{/link}, perto da fronteira com as {link:eastern-plaguelands}Terras Pestilentas Orientais{/link}. O último dos quatro caldeirões do oeste ergue-se aqui. É guardado por espectros e fantasmas, entre os servos mais perigosos do {link:scourge}Flagelo{/link} nestas terras, e pelo senhor do caldeirão Soulwrath. Nenhum registro diz quem foi Gahrron, ou o que foi feito do povo da fazenda.]=],
		},
	},
})

Translate("ptBR", "sorrow-hill", {
	title = "Colina do Pesar",
	sections = {
		{
			title = "Resumo",
			text = [=[A Colina do Pesar é o grande cemitério do sul das Terras Pestilentas, entre o {link:chillwind-camp}Acampamento Ventogelante{/link} e {link:ruins-of-andorhal}Andorhal{/link}. Suas encostas estão cobertas de túmulos, criptas e monumentos, entre eles a tumba de {link:uther-the-lightbringer}Uther, o Portador da Luz{/link}. Os mortos não descansam aqui. Esqueletos e carniçais se erguem dos túmulos em tamanho número que o {link:scourge}Flagelo{/link} usa a colina como uma muralha viva diante da estrada leste para Andorhal. Entre as lápides caminha o fantasma de {link:marlene-redpath}Marlene Redpath{/link}, que ainda busca notícias da sobrinha que escondeu na batalha da {link:darrowshire}Vila das Flechas{/link}.]=],
		},
	},
})

Translate("ptBR", "uther-s-tomb", {
	title = "Tumba de Uther",
	sections = {
		{
			title = "Resumo",
			text = [=[A Tumba de Uther ergue-se na {link:sorrow-hill}Colina do Pesar{/link}, uma casa de pedra construída em memória de {link:uther-the-lightbringer}Uther, o Portador da Luz{/link}, o primeiro dos paladinos do Punho de Prata. Uma grande estátua do Portador da Luz ergue-se em seu interior. É um dos poucos lugares das Terras Pestilentas que os vivos ainda mantêm. O {link:high-priest-thel-danis}Sumo Sacerdote Thel'danis{/link} guarda a tumba e purifica o mal das pedras dos mortos. Uma velha chamada {link:myranda-the-hag}Myranda{/link} também vive ali. Ela foi um dia conselheira de confiança de {link:tirion-fordring}Tirion Fordring{/link}.]=],
		},
	},
})

Translate("ptBR", "caer-darrow", {
	title = "Castro das Flechas",
	aliases = { "Lago das Flechas" },
	sections = {
		{
			title = "Resumo",
			text = [=[Castro das Flechas é um castelo insular no Lago das Flechas, no sudeste das {link:western-plaguelands}Terras Pestilentas Ocidentais{/link}. Por gerações foi a sede da família Barov, e um lugar aprazível aonde os nobres de {link:lordaeron}Lordaeron{/link} vinham descansar à beira d'água. Os Barov o entregaram ao {link:cult-of-the-damned}Culto dos Malditos{/link}. Nas criptas sob o castelo, o culto fundou a Scolomântia, sua escola de necromancia. A cidade em volta do castelo está vazia de vivos. Seus fantasmas permanecem: cidadãos, guardas, um padeiro e seus filhos, um pintor na margem. A maioria deles revive sem parar seu último dia feliz. Alguns se lembram de tudo, e querem a escola destruída.]=],
		},
	},
})

Translate("ptBR", "taelan-fordring", {
	title = "Taelan Fordring",
	subtitle = "Grão-senhor da Cruzada Escarlate",
	found = "Dentro da Bastilha Mardenforte, em Amparo",
	hint = [=[Procure o grão-senhor no castelo de Amparo. A Cruzada não acolhe estranhos.]=],
	allegiance = "Cruzada Escarlate",
	aliases = { "Taelan", "Grão-senhor Taelan Fordring" },
	sections = {
		{
			title = "Resumo",
			text = [=[Taelan Fordring é o Grão-senhor da {link:scarlet-crusade}Cruzada Escarlate{/link} em {link:hearthglen}Amparo{/link}. Comanda seus cavaleiros a partir da Bastilha Mardenforte, a casa onde nasceu. É filho de {link:tirion-fordring}Tirion Fordring{/link}, outrora senhor destas terras. Taelan era menino quando o pai foi banido, e lhe disseram que o pai tinha morrido. Ele acredita nisso desde então.]=],
		},
		{
			title = "Importância",
			text = [=[Taelan é o último dos Fordring a possuir as terras de sua família, e as possui para uma ordem que perdeu o rumo. Foi criado na Luz e treinado como paladino do Punho de Prata. Combateu o {link:scourge}Flagelo{/link} quando o reino caiu. De todos os líderes da Cruzada, é aquele em quem algo da velha ordem ainda vive.]=],
		},
		{
			title = "Primeiros Anos",
			text = [=[Taelan cresceu na Bastilha Mardenforte, filho do Lorde {link:tirion-fordring}Tirion{/link} e de sua esposa Karandra. Quando era pequeno, o pai lhe deu um martelo de guerra em miniatura, feito à semelhança do seu. Então veio o julgamento. Tirion havia poupado a vida de um {link:orcs}orc{/link}, e por isso foi destituído de suas terras e títulos e expulso da ordem. Karandra disse ao filho que o pai estava morto. Taelan enterrou o martelo de brinquedo no falso túmulo e cresceu sem ele.]=],
		},
		{
			title = "A Queda da Ordem",
			text = [=[Taelan seguiu o caminho do pai nos Cavaleiros do Punho de Prata. Quando {link:uther-the-lightbringer}Uther{/link} caiu e a ordem foi desfeita, continuou lutando ao lado dos últimos de seus cavaleiros. No povoado do {link:northdale}Vilarejo do Norte{/link}, resistiu até o fim. Ali, em desespero, lançou por terra o estandarte do Punho de Prata e renunciou à ordem. Em vez dela, uniu-se à {link:scarlet-crusade}Cruzada Escarlate{/link}, e subiu alto nela.]=],
		},
		{
			title = "Feitos",
			text = [=[• Treinou como paladino do Punho de Prata.
• Combateu o {link:scourge}Flagelo{/link} na queda de {link:lordaeron}Lordaeron{/link}, e resistiu até o fim no {link:northdale}Vilarejo do Norte{/link}.
• Renunciou ao Punho de Prata e uniu-se à {link:scarlet-crusade}Cruzada Escarlate{/link}.
• Comanda a Cruzada em {link:hearthglen}Amparo{/link} como seu Grão-senhor.]=],
		},
	},
	chapters = {
		{
			title = "O Presente de Tirion",
			hint = [=[Leve o presente de um pai para dentro de Amparo, disfarçado como um de seus defensores.]=],
			text = [=[O mensageiro chegou à Bastilha Mardenforte com o tabardo de um cruzado, e Taelan o tomou por um dos reforços esperados da {link:tyr-s-hand}Manopla de Tyr{/link}. Então abriu a caixa. Dentro estavam o martelo de brinquedo do túmulo de seu pai, o estandarte que ele lançara por terra no {link:northdale}Vilarejo do Norte{/link} e um retrato dele próprio quando criança, nos braços do pai e da mãe, na margem de {link:caer-darrow}Castro das Flechas{/link}. Não eram relíquias de um morto. Taelan caiu de joelhos. Entendeu que o pai estava vivo, e que tinham mentido para ele durante a maior parte da vida.]=],
		},
		{
			title = "Em Sonhos",
			hint = "Ajude o grão-senhor a deixar Amparo.",
			text = [=[Taelan havia muito sonhava com o pai, lutando a seu lado contra os mortos. Agora escolheu ir até ele. Rejeitou a Cruzada a que servira por tanto tempo e abriu caminho à força para fora de {link:hearthglen}Amparo{/link}. Além das muralhas, a Cruzada veio atrás dele. O Grande Inquisidor Isillien o alcançou na estrada e o matou diante dos olhos do pai. {link:tirion-fordring}Tirion{/link} ajoelhou-se sobre o corpo do filho. De sua dor nasceu um juramento: o Punho de Prata não estava morto, e ele o reergueria.]=],
		},
	},
	mentions = {
		{
			text = [=[Das Memórias Esquecidas, o martelo de brinquedo no falso túmulo]=],
		},
		{
			text = [=[Da Honra Perdida, o estandarte do {link:northdale}Vilarejo do Norte{/link}]=],
		},
		{ text = "Do Amor e da Família, o retrato" },
		{ text = "Encontre {link:myranda-the-hag}Myranda{/link}" },
		{ text = "Subterfúgio Escarlate" },
		{ text = "Em Sonhos" },
	},
	bonds = {
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "seu pai" },
		{ id = "myranda-the-hag", name = "Myranda, a Bruxa", note = "a conselheira de seu pai" },
		{ id = "artist-renfray", name = "Artista Renfray", note = "pintou-o quando criança" },
		{ id = "uther-the-lightbringer", name = "Uther, o Portador da Luz", note = "liderava a ordem a que ele renunciou" },
	},
})

Translate("ptBR", "commander-ashlam-valorfist", {
	title = "Comandante Ashlam Valorfist",
	subtitle = "Comandante do Acampamento Ventogelante",
	found = [=[Acampamento Ventogelante, no sul das Terras Pestilentas Ocidentais]=],
	hint = [=[Fale com o comandante que reúne a Aliança no Acampamento Ventogelante.]=],
	allegiance = "Reino de Ventobravo · Aliança",
	aliases = { "Ashlam Valorfist", "Valorfist" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Comandante Ashlam Valorfist lidera a {link:alliance}Aliança{/link} nas {link:western-plaguelands}Terras Pestilentas Ocidentais{/link}. Quando {link:stormwind-city}Ventobravo{/link} lançou seu chamado às armas contra o {link:scourge}Flagelo{/link} do norte, foi a seu acampamento que os voluntários foram enviados. É um homem ousado e barulhento, afeito a planos e a elogios, e pretende tomar {link:ruins-of-andorhal}Andorhal{/link} de volta dos mortos.]=],
		},
		{
			title = "Importância",
			text = [=[Valorfist é a espada da {link:alliance}Aliança{/link} nas terras mortas de {link:lordaeron}Lordaeron{/link}. Sua campanha é a primeira tentativa real de {link:stormwind-city}Ventobravo{/link} de golpear o {link:scourge}Flagelo{/link} em seu próprio território desde a queda do reino.]=],
		},
		{
			title = "Feitos",
			text = [=[• Construiu o {link:chillwind-camp}Acampamento Ventogelante{/link} e convocou voluntários para ele em nome de {link:stormwind-city}Ventobravo{/link}.
• Planejou o ataque a {link:ruins-of-andorhal}Andorhal{/link} pela estrada leste, através da {link:sorrow-hill}Colina do Pesar{/link}.
• Ordenou que as torres de vigia de Andorhal fossem marcadas para o assalto.
• Encarregou seus sacerdotes de voltar os caldeirões da praga contra o {link:scourge}Flagelo{/link}.
• Enviou campeões em busca da chave da Scolomântia.]=],
		},
	},
	chapters = {
		{
			title = "A Estrada pela Colina do Pesar",
			hint = [=[Livre dos mortos a colina que guarda a estrada leste de Andorhal.]=],
			text = [=[As estradas oeste e norte para {link:ruins-of-andorhal}Andorhal{/link} estavam guardadas com força demais. Valorfist escolheu a estrada leste. Para alcançá-la, suas forças precisavam passar pela {link:sorrow-hill}Colina do Pesar{/link}, onde os mortos se erguiam de seus túmulos às centenas. O primeiro golpe de sua campanha foi desferido entre as lápides.]=],
		},
		{
			title = "As Torres de Vigia",
			hint = "Marque as torres de Andorhal para o assalto.",
			text = [=[O {link:scourge}Flagelo{/link} usava quatro torres de vigia para guiar suas forças por {link:ruins-of-andorhal}Andorhal{/link}. Valorfist mandou fazer uma tocha-farol, e com ela as torres foram marcadas uma a uma. Seus sacerdotes sentiram os faróis arderem fortes. O comandante declarou que chegara a hora de levar a luta para dentro da cidade.]=],
		},
		{
			title = "Os Caldeirões",
			hint = [=[Ajude os sacerdotes do comandante a voltar os caldeirões da praga contra o Flagelo.]=],
			text = [=[Os caldeirões não podiam ser destruídos. A necromancia de {link:kel-thuzad}Kel'Thuzad{/link} era forte demais. Então a segunda em comando de Valorfist, a {link:high-priestess-macdonnell}Alta Sacerdotisa MacDonnell{/link}, planejou mudar o que eles preparavam. Os quatro caldeirões do oeste foram abertos, seus venenos recolhidos, e um contra-agente foi feito. Quando isso terminou, o comandante se pôs diante de seu acampamento e bradou seu agradecimento ao campeão que o fizera, como a um herói da {link:alliance}Aliança{/link}.]=],
		},
		{
			title = "Ai, Andorhal",
			hint = "Destrua o lich que governa Andorhal.",
			text = [=[Por fim, Valorfist enviou seus campeões ao coração de {link:ruins-of-andorhal}Andorhal{/link}, contra o lich {link:araj-the-summoner}Araj, o Invocador{/link}. Eles voltaram com um fragmento do filactério do lich. O comandante chamou aquilo de uma vitória para a posteridade.]=],
		},
	},
	mentions = {
		{ text = "Chamado às Armas: As Terras Pestilentas!" },
		{ text = "Abram Caminho" },
		{ text = "Por Todas as Torres de Vigia" },
		{ text = "Os Caldeirões do {link:scourge}Flagelo{/link}" },
		{ text = "Missão Cumprida!" },
		{ text = "Scolomântia" },
		{ text = "Ai, {link:ruins-of-andorhal}Andorhal{/link}" },
		{
			text = [=[{link:chillwind-point}Morro do Ventogelante{/link}, notícias do {link:grayson-shadowbreaker}Lorde Grayson Shadowbreaker{/link}]=],
		},
		{ text = "Pedras do {link:scourge}Flagelo{/link} Inertes" },
		{
			text = [=[Forjando a Pedra do Poder, com penas dos trolls do templo submerso]=],
		},
	},
	bonds = {
		{ id = "high-priestess-macdonnell", name = "Alta Sacerdotisa MacDonnell", note = "sua segunda em comando" },
		{ id = "alchemist-arbington", name = "Alquimista Arbington", note = "seu estudioso da Scolomântia" },
		{ id = "high-priest-thel-danis", name = "Sumo Sacerdote Thel'danis", note = "purifica as pedras de que ele precisa" },
		{ id = "grayson-shadowbreaker", name = "Grayson Shadowbreaker", note = "envia-lhe paladinos" },
		{ id = "high-executor-derrington", name = "Alto Executor Derrington", note = "o comandante da Horda com o mesmo objetivo" },
		{ id = "araj-the-summoner", name = "Araj, o Invocador", note = "inimigo" },
	},
})

Translate("ptBR", "high-executor-derrington", {
	title = "Alto Executor Derrington",
	subtitle = "Comandante do Baluarte",
	found = "O Baluarte, na borda leste de Tirisfal",
	hint = "Fale com o alto executor que defende o Baluarte.",
	allegiance = "Renegados · Horda",
	aliases = { "Derrington" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Alto Executor Derrington comanda os {link:forsaken}Renegados{/link} no {link:the-bulwark}Baluarte{/link}, o portão fortificado entre {link:tirisfal-glades}Tirisfal{/link} e as Terras Pestilentas. Quando a {link:horde}Horda{/link} convocou seus campeões contra o {link:scourge}Flagelo{/link} do norte, eles foram enviados a ele. É um comandante astuto. Não combate dois inimigos ao mesmo tempo quando pode jogá-los um contra o outro.]=],
		},
		{
			title = "Importância",
			text = [=[Derrington defende a fronteira leste do reino da Dama Sombria. {link:the-bulwark}O Baluarte{/link} é a muralha entre a {link:undercity}Cidade Baixa{/link} e as terras mortas, e dele ele lidera a guerra dos {link:forsaken}Renegados{/link} para tomar {link:ruins-of-andorhal}Andorhal{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Defende o {link:the-bulwark}Baluarte{/link} para os {link:forsaken}Renegados{/link} e a {link:horde}Horda{/link}.
• Jogou a {link:scarlet-crusade}Cruzada Escarlate{/link} contra o {link:scourge}Flagelo{/link} com uma tenda queimada e um estandarte falso.
• Ordenou que as torres de vigia de {link:ruins-of-andorhal}Andorhal{/link} fossem marcadas para o assalto.
• Encarregou seus sacerdotes das sombras de voltar os caldeirões da praga contra o Flagelo.
• Enviou campeões em busca da chave da Scolomântia.]=],
		},
	},
	chapters = {
		{
			title = "Distrações Escarlates",
			hint = "Ponha a Cruzada e o Flagelo um contra a garganta do outro.",
			text = [=[A {link:scarlet-crusade}Cruzada Escarlate{/link} havia avançado ao sul de {link:hearthglen}Amparo{/link} e acampado entre o {link:felstone-field}Campo Pedravil{/link} e as {link:dalson-s-tears}Lágrimas de Dalson{/link}. Derrington não queria combater a Cruzada e o {link:scourge}Flagelo{/link} ao mesmo tempo. Mandou queimar a tenda de comando da Cruzada com chama engarrafada e plantar um estandarte do Flagelo ao lado das cinzas. Depois enviou um batedor para ver os cruzados morderem a isca.]=],
		},
		{
			title = "As Torres de Vigia",
			hint = "Marque as torres de Andorhal para o assalto.",
			text = [=[Com a Cruzada distraída, Derrington voltou-se para {link:ruins-of-andorhal}Andorhal{/link}. Os mortos usavam quatro torres de vigia para guiar seus movimentos. Seus bruxos fizeram uma tocha-farol, e as torres foram marcadas para o ataque. O alto executor ficou satisfeito. Agora, disse ele, seria uma luta direta pela cidade.]=],
		},
		{
			title = "Os Caldeirões",
			hint = [=[Ajude os sacerdotes das sombras a voltar os caldeirões da praga contra o Flagelo.]=],
			text = [=[Os quatro caldeirões do oeste não podiam ser desligados, mas podiam ser mudados. A {link:shadow-priestess-vandis}Sacerdotisa das Sombras Vandis{/link} cuidou do trabalho. Quando os quatro foram abertos e seus venenos voltados contra seus criadores, Derrington proclamou diante de todo o {link:the-bulwark}Baluarte{/link} o nome do campeão que o fizera.]=],
		},
		{
			title = "Ai, Andorhal",
			hint = "Destrua o lich que governa Andorhal.",
			text = [=[Por último veio o golpe contra o lich {link:araj-the-summoner}Araj, o Invocador{/link}. Seus campeões trouxeram de volta um fragmento do filactério do lich, e Derrington o proclamou uma vitória da {link:horde}Horda{/link}.]=],
		},
	},
	mentions = {
		{ text = "Chamado às Armas: As Terras Pestilentas!" },
		{ text = "Distrações Escarlates" },
		{ text = "Por Todas as Torres de Vigia" },
		{ text = "Os Caldeirões do {link:scourge}Flagelo{/link}" },
		{ text = "Missão Cumprida!" },
		{ text = "Scolomântia" },
		{ text = "A Chave da Scolomântia" },
		{ text = "Ai, {link:ruins-of-andorhal}Andorhal{/link}" },
	},
	bonds = {
		{ id = "shadow-priestess-vandis", name = "Sacerdotisa das Sombras Vandis", note = "sua segunda em comando" },
		{ id = "apothecary-dithers", name = "Boticário Dithers", note = "seu estudioso da Scolomântia" },
		{ id = "alexi-barov", name = "Alexi Barov", note = "um lorde sob sua proteção" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sua rainha" },
		{ id = "commander-ashlam-valorfist", name = "Comandante Ashlam Valorfist", note = "o comandante da Aliança com o mesmo objetivo" },
		{ id = "araj-the-summoner", name = "Araj, o Invocador", note = "inimigo" },
	},
})

Translate("ptBR", "chromie", {
	title = "Chromie",
	subtitle = "A Estranha Historiadora",
	found = "A estalagem em ruínas no canto noroeste de Andorhal",
	hint = "Procure a gnoma que vive na estalagem em ruínas de Andorhal.",
	allegiance = "Desconhecida",
	sections = {
		{
			title = "Resumo",
			text = [=[Chromie é uma pequena gnoma que fez seu lar na estalagem em ruínas de {link:ruins-of-andorhal}Andorhal{/link}, numa cidade dominada pelos mortos. O quarto que ela ocupa está estranhamente intacto, como se a ruína à sua volta não o tivesse tocado. Ela fala do tempo como outros falam do clima. Pergunta aos viajantes se vêm do futuro, e não parece estar brincando.]=],
		},
		{
			title = "Importância",
			text = [=[Chromie afirma que algo mexeu com o fluxo do tempo em {link:ruins-of-andorhal}Andorhal{/link}, e que ela veio consertá-lo. O que quer que ela seja, sabe muito mais do que uma gnoma deveria sobre o passado da cidade, e sobre o destino dos que morreram na guerra.]=],
		},
		{
			title = "Feitos",
			text = [=[• Mantém um quarto na estalagem em ruínas de {link:ruins-of-andorhal}Andorhal{/link}.
• Caça as criaturas que se alimentam do fluxo partido do tempo na cidade.
• Reúne os relógios parados de Andorhal.
• Busca descobrir o destino de {link:joseph-redpath}Joseph Redpath{/link}, da {link:darrowshire}Vila das Flechas{/link}, e mudá-lo.]=],
		},
	},
	chapters = {
		{
			title = "Uma Questão de Tempo",
			hint = [=[Ajude a gnoma da estalagem com os parasitas dos silos de Andorhal.]=],
			text = [=[Chromie disse que a linha do tempo de {link:ruins-of-andorhal}Andorhal{/link} havia sido adulterada, muito provavelmente pelo {link:scourge}Flagelo{/link}. Criaturas que se alimentam do tempo partido tinham se reunido nos silos, e atrapalhavam seu trabalho. Quando foram arrancadas de lá, ela falou mais abertamente. Não é uma gnoma de fato. Serve à Revoada {link:the-drag}Drag{/link}ônica Bronze, os guardiões do tempo, e sua verdadeira forma está oculta.]=],
		},
		{
			title = "Contando o Tempo",
			hint = "Leve a Chromie os relógios parados de Andorhal.",
			text = [=[Para reparar o dano a {link:ruins-of-andorhal}Andorhal{/link}, Chromie trabalha a partir de outro fio do tempo, para não perturbá-lo ainda mais. Precisa de objetos do momento em que a praga atacou. Os relógios da cidade servem, pois todos pararam às três horas, a hora em que a praga se espalhou pela primeira vez. O que Chromie dá em troca são presentes cujo uso, diz ela, ficará claro com o tempo.]=],
		},
		{
			title = "Os Anais da Vila das Flechas",
			hint = [=[Encontre a crônica da Vila das Flechas na prefeitura de Andorhal.]=],
			text = [=[O fantasma de {link:marlene-redpath}Marlene Redpath{/link} enviou um anel a Chromie, o anel de casamento de {link:joseph-redpath}Joseph Redpath{/link}. Chromie soube na hora que ele pertencera a um grande homem de passado trágico. Os Anais da {link:darrowshire}Vila das Flechas{/link}, guardados na prefeitura de {link:ruins-of-andorhal}Andorhal{/link}, contaram o resto: na batalha pela Vila das Flechas, Joseph foi corrompido e voltado contra os defensores dela. Chromie decidiu mudar esse destino, se pudesse.]=],
		},
	},
	mentions = {
		{ text = "Uma Questão de Tempo" },
		{ text = "Contando o Tempo" },
		{ text = "Uma Estranha Historiadora" },
		{ text = "Os Anais da {link:darrowshire}Vila das Flechas{/link}" },
		{ text = "{link:carlin-redpath}Irmão Carlin{/link}" },
		{ text = "De Volta a Chromie" },
		{ text = "A Batalha da {link:darrowshire}Vila das Flechas{/link}" },
	},
	bonds = {
		{ id = "marlene-redpath", name = "Marlene Redpath", note = "enviou-lhe o anel de Joseph" },
		{ id = "jeziba", name = "Jeziba", note = "divide com ela seu canto da cidade em ruínas" },
	},
})

Translate("ptBR", "araj-the-summoner", {
	title = "Araj, o Invocador",
	subtitle = "Lich de Andorhal",
	found = "O coração das ruínas de Andorhal",
	hint = "Enfrente o lich que domina o coração de Andorhal.",
	allegiance = "Flagelo",
	aliases = { "Araj" },
	sections = {
		{
			title = "Resumo",
			text = [=[Araj, o Invocador, é um lich do {link:scourge}Flagelo{/link}. Exerce domínio sobre as ruínas de {link:ruins-of-andorhal}Andorhal{/link} a partir do coração da cidade, guardado pelos mortos que cercam seu centro e por um séquito próprio. Tanto a {link:alliance}Aliança{/link} quanto os {link:forsaken}Renegados{/link} o apontaram como o senhor de Andorhal e aquele que precisam destruir.]=],
		},
		{
			title = "Importância",
			text = [=[Araj já comandou a Scolomântia, a escola de necromancia do culto sob {link:caer-darrow}Castro das Flechas{/link}, antes de reivindicar {link:ruins-of-andorhal}Andorhal{/link} para si. Seu sinete, um escaravelho, é uma das poucas coisas capazes de abrir a porta selada da escola.]=],
		},
		{
			title = "Feitos",
			text = [=[• Comandou a Scolomântia antes de tomar {link:ruins-of-andorhal}Andorhal{/link}.
• Governa as ruínas de Andorhal para o {link:scourge}Flagelo{/link}.
• Seu escaravelho é a cabeça da chave da Scolomântia.]=],
		},
	},
	chapters = {
		{
			title = "O Escaravelho",
			hint = [=[Descubra o que os alquimistas das Terras Pestilentas precisam do lich.]=],
			text = [=[A porta da Scolomântia só pode ser aberta por uma chave feita de osso e unida ao sinete de alguém que pudesse abri-la por direito. Araj foi um dia o mestre da escola. Seu escaravelho, tirado de seu filactério caído, tornou-se a cabeça da chave.]=],
		},
		{
			title = "A Queda de Araj",
			hint = "Destrua o lich de Andorhal.",
			text = [=[Campeões da {link:alliance}Aliança{/link} e da {link:horde}Horda{/link} invadiram o coração de {link:ruins-of-andorhal}Andorhal{/link} e abriram caminho entre os guardas do lich. Derrubaram seu filactério, e um fragmento dele foi levado ao {link:chillwind-camp}Acampamento Ventogelante{/link} e ao {link:the-bulwark}Baluarte{/link} como prova.]=],
		},
	},
	mentions = {
		{ text = "Ai, {link:ruins-of-andorhal}Andorhal{/link}" },
		{ text = "O Escaravelho de Araj" },
	},
	bonds = {
		{ id = "commander-ashlam-valorfist", name = "Comandante Ashlam Valorfist", note = "inimigo" },
		{ id = "high-executor-derrington", name = "Alto Executor Derrington", note = "inimigo" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "o mestre de seu mestre" },
	},
})

Translate("ptBR", "myranda-the-hag", {
	title = "Myranda, a Bruxa",
	subtitle = "A Ilusionista da Tumba de Uther",
	found = "Na Tumba de Uther, na Colina do Pesar",
	hint = "Procure a velha que vive junto à tumba do Portador da Luz.",
	allegiance = "Nenhuma (antes, a casa de Tirion Fordring)",
	aliases = { "Myranda" },
	sections = {
		{
			title = "Resumo",
			text = [=[Myranda é uma velha que vive na {link:uther-s-tomb}Tumba de Uther{/link} e diz ser ilusionista. Um dia foi a conselheira de maior confiança de {link:tirion-fordring}Tirion Fordring{/link}, quando ele era Lorde de Mardenforte. Quando a ordem o condenou, ela falou abertamente contra o veredito, e foi banida por isso. Há muito tempo espera uma chance de reparar as injustiças feitas aos Fordring.]=],
		},
		{
			title = "Feitos",
			text = [=[• Aconselhou {link:tirion-fordring}Tirion Fordring{/link} quando ele era Lorde de Mardenforte.
• Foi banida por se opor ao veredito contra ele.
• Lança ilusões que permitem a estranhos andar entre inimigos.]=],
		},
	},
	chapters = {
		{
			title = "Subterfúgio Escarlate",
			hint = "Leve à velha um presente de Tirion.",
			text = [=[Quando o mensageiro de {link:tirion-fordring}Tirion{/link} chegou até ela, Myranda disse apenas que sabia que aquele dia chegaria. Lançou sobre o mensageiro a aparência de um cruzado escarlate, para que o presente de Tirion pudesse ser levado para dentro de {link:hearthglen}Amparo{/link}. A ilusão lhe custa caro, e se desfaz se seu portador se afastar demais destas terras.]=],
		},
	},
	mentions = {
		{ text = "Encontre Myranda" },
		{ text = "Subterfúgio Escarlate" },
		{
			text = [=[O Testamento de {link:rexxar}Rexxar{/link}, uma tarefa para a {link:horde}Horda{/link}]=],
		},
		{ text = "Ilusões do Óculo" },
